Lemma round fx R p :
  getr R (reg 2) = Z_to_bv 64 (Sp - 16) -> getr R (reg 13) = Z_to_bv 64 b -> getr R (reg 15) = Z_to_bv 64 24 -> getr R (reg 16) = Z_to_bv 64 p ->
