  exists fx' R', (forall x, In x KSL -> getr R' (reg x) = getr R (reg x)) /\
    (   (msteps RSEGS (st fx R 0xb4900 M) (st fx' R' 0xb4900 M) /\ getr R' (reg 16) = Z_to_bv 64 (p - 24) /\ p - 24 <> b)
